import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import test from "node:test";

const root = resolve(fileURLToPath(new URL("..", import.meta.url)));
const baselinePath = resolve(root, "fixtures/operational-state/current-baseline/facts.json");
const resolverPath = resolve(root, "scripts/resolve-execution-state.mjs");
const authority = JSON.parse(readFileSync(resolve(root, "docs/issues.json"), "utf8")).operational_authority;
const expectedBootstrap = ["planning-contract (22)", "planning-contract (24)"].sort();
const expectedPostC = [...expectedBootstrap, "operational-state-offline"].sort();
const expectedNames = new Set(expectedPostC);

const clone = (value) => JSON.parse(JSON.stringify(value));
const loadFacts = () => JSON.parse(readFileSync(baselinePath, "utf8"));
const codesFor = (result, ticketId) => (result.tickets[ticketId]?.blockers ?? []).map(({ code }) => code);

const stringLeaves = (value) => {
  if (typeof value === "string") return [value];
  if (Array.isArray(value)) return value.flatMap(stringLeaves);
  if (value && typeof value === "object") return Object.values(value).flatMap(stringLeaves);
  return [];
};

const phaseFor = (context) => {
  const text = context.join(" ").toLowerCase();
  const bootstrap = /bootstrap|not[_\s-]*required.*d0[_\s-]*004c|(?:before|pre)[_\s-]*d0[_\s-]*004c/.test(text);
  const postC = /(?:post|after)[_\s-]*d0[_\s-]*004c|d0[_\s-]*004c.*merg|resolver_and_workflow/.test(text);
  if (bootstrap === postC) return null;
  return bootstrap ? "bootstrap" : "postC";
};

// The catalog may publish a phase set as full check records or as phase-scoped names
// referring to its check records. This deliberately does not require one storage shape.
const publishedPhaseSets = (policy) => {
  const sets = { bootstrap: new Set(), postC: new Set() };
  const walk = (value, context = []) => {
    if (Array.isArray(value)) {
      if (value.length && value.every((entry) => entry && typeof entry.name === "string" && typeof entry.workflow_path === "string")) {
        for (const check of value) {
          const phase = phaseFor([...context, ...stringLeaves(check)]);
          if (phase) sets[phase].add(check.name);
        }
        return;
      }
      const namedChecks = value.filter((entry) => typeof entry === "string" && expectedNames.has(entry));
      if (namedChecks.length && context.some((entry) => /candidate/i.test(entry))) {
        const phase = phaseFor(context);
        if (phase) for (const name of namedChecks) sets[phase].add(name);
      }
      for (const entry of value) walk(entry, context);
      return;
    }
    if (!value || typeof value !== "object") return;
    for (const [key, child] of Object.entries(value)) {
      walk(child, [...context, key, ...(typeof child === "string" ? [child] : [])]);
    }
  };
  walk(policy);
  return Object.fromEntries(Object.entries(sets).map(([phase, names]) => [phase, [...names].sort()]));
};

const addAcceptedD0004Gate = (facts) => {
  const ticket = facts.tickets["D0-004"];
  const ticketPath = Object.keys(facts.liveDigests).find((path) => path.includes("/D0-004-"));
  const artifacts = [
    { path: ticketPath, sha256: ticket.digests.ticket, kind: "TICKET" },
    { path: ticket.prd_path, sha256: ticket.digests.prd, kind: "PRD" },
    ...Object.entries(ticket.digests.adrs).map(([adr, sha256]) => ({
      path: ticket.adr_paths[adr], sha256, kind: "ADR"
    }))
  ];
  facts.gateBatches.push({ id: "batch-phase-scope", status: "ACCEPTED", required_artifacts: artifacts });
  facts.gatePRs.push({
    number: 900,
    base: "dev",
    head_sha: "dddddddddddddddddddddddddddddddddddddddd",
    body: "Gate-Batch: batch-phase-scope",
    merged: true,
    merged_by: "MongLong0214",
    merge_commit_sha: "eeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeee",
    author: "MongLong0214",
    head_contains_batch: true
  });
  facts.postMergeCI.push({
    merge_commit_sha: "eeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeee",
    head_sha: "eeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeee",
    status: "completed",
    conclusion: "success"
  });
};

const candidateFactsWithoutOfflineCheck = (d0_004c_merged) => {
  const facts = loadFacts();
  const head = "cafecafecafecafecafecafecafecafecafecafe";
  facts.operationalAuthority = clone(authority);
  facts.d0_004c_merged = d0_004c_merged;
  facts.liveBaseSha = facts.currentHead;
  facts.prs = [{
    number: 300,
    ticket_id: "D0-004",
    base: "dev",
    base_sha: facts.currentHead,
    head_sha: head,
    author: "MongLong0214",
    body: "Ticket: D0-004",
    merged: false,
    labels: []
  }];
  facts.workflowBlobs[".github/workflows/ci.yml"].heads = { [head]: "ci-blob-dev" };
  facts.workflowBlobs[".github/workflows/operational-state.yml"].heads = { [head]: "ops-blob-dev" };
  facts.checkRuns = [];
  facts.workflowRuns = [];
  for (const [index, name] of expectedBootstrap.entries()) {
    const entry = {
      name,
      head_sha: head,
      status: "completed",
      conclusion: "success",
      app_slug: "github-actions",
      app_id: 15368,
      event: "pull_request",
      base: "dev",
      workflow_path: ".github/workflows/ci.yml",
      run_id: index + 10,
      run_attempt: 1,
      ticket_id: "D0-004"
    };
    facts.checkRuns.push({ ...entry });
    facts.workflowRuns.push({ ...entry });
  }
  if (d0_004c_merged) addAcceptedD0004Gate(facts);
  return facts;
};

const resolveOffline = async (facts) => {
  const { resolveExecutionState } = await import(pathToFileURL(resolverPath).href);
  return resolveExecutionState({
    mode: "offline",
    root,
    facts,
    runtimeIdentity: { repository: facts.repository, branch: facts.defaultBranch, head: facts.currentHead }
  });
};

test("operational authority publishes and enforces phase-scoped candidate CI", async () => {
  const sets = publishedPhaseSets(authority);
  assert.deepEqual(sets.bootstrap, expectedBootstrap, "Bootstrap must publish its complete candidate-check set");
  assert.deepEqual(sets.postC, expectedPostC, "post-D0-004C must publish its complete candidate-check set");

  const bootstrap = await resolveOffline(candidateFactsWithoutOfflineCheck(false));
  assert.equal(codesFor(bootstrap, "D0-004").includes("EXACT_HEAD_CI_FAILED"), false,
    "the deferred offline check must not block Bootstrap");

  const postC = await resolveOffline(candidateFactsWithoutOfflineCheck(true));
  assert.equal(codesFor(postC, "D0-004").includes("EXACT_HEAD_CI_FAILED"), true,
    "after D0-004C, the missing offline check must fail closed");
});
